import{_ as o,o as e,c as r,a3 as l}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Atualizar localizadores da capa após novo evento","description":"","frontmatter":{"title":"Atualizar localizadores da capa após novo evento","id":"eproc-atualizar-localizadores-capa","plataforma":"eproc","grupo":"Painel do processo","plano":"free","desde":"1.15.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-atualizar-localizadores-capa"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-atualizar-localizadores-capa"}],["meta",{"property":"og:title","content":"Atualizar localizadores da capa após novo evento | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-atualizar-localizadores-capa.md","filePath":"funcionalidades/eproc-atualizar-localizadores-capa.md"}'),s={name:"funcionalidades/eproc-atualizar-localizadores-capa.md"};function i(t,a,c,n,d,p){return e(),r("div",null,a[0]||(a[0]=[l('<h1 id="atualizar-localizadores-da-capa-apos-novo-evento" tabindex="-1">Atualizar localizadores da capa após novo evento <a class="header-anchor" href="#atualizar-localizadores-da-capa-apos-novo-evento" aria-label="Permalink to &quot;Atualizar localizadores da capa após novo evento&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Algumas operações lançam um evento no processo e, com isso, mudam os localizadores, mas o eproc só atualiza a tabela de eventos e a capa continua mostrando os localizadores anteriores. Este recurso percebe o evento novo e atualiza a linha &quot;Localizador(es):&quot; da capa, sem recarregar a página.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, na linha &quot;Localizador(es):&quot; da capa.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Na página do processo, faça uma operação que lance um evento sem recarregar a página.</li><li>Quando o evento novo aparece na tabela de eventos, os localizadores da capa são atualizados sozinhos, cerca de um segundo depois.</li><li>Um pequeno brilho ao lado de &quot;Localizador(es):&quot; indica que a atualização foi feita pelo eploc. Passe o mouse sobre ele para ver o horário.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar ou desligar o recurso.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Só eventos novos disparam a atualização. Trocar de página de eventos, mudar os filtros ou carregar todas as páginas não dispara nada.</li><li>Se o editor de localizadores estiver aberto, a capa não é atualizada, para não descartar o que você está editando.</li><li>Se a atualização não der certo, a capa fica como estava e a página não é recarregada.</li><li>O brilho some quando o próprio eproc redesenha a linha de localizadores, por exemplo ao salvar uma alteração neles.</li><li>Com as animações desligadas (aba Geral), o brilho aparece sem animação.</li></ul>',11)]))}const h=o(s,[["render",i]]);export{m as __pageData,h as default};
